import { categoryLabel } from './category-data.ts'
import { monthlyEquivalent } from './money.ts'
import type { Expense } from './types.ts'

/**
 * Renewals & price changes (Phase 6 §4.6). Pure: what a published price event costs THIS person, their own expected
 * increases, renewal reminders and the merged "coming up" timeline.
 */

export const PRICE_EVENT_KINDS = ['fuel', 'electricity', 'water', 'municipal', 'medical_aid', 'insurance', 'cellphone', 'other'] as const
export type PriceEventKind = (typeof PRICE_EVENT_KINDS)[number]

/** Mirrors public.price_events — Migration 030. */
export interface PriceEvent {
  id: string
  kind: PriceEventKind
  title: string
  description: string
  effective_on: string
  category: string
  change_pct: number | null
  change_amount: number | null
  change_unit: 'c/l' | 'R' | null
  region: 'all' | 'inland' | 'coastal'
  source_url: string | null
  status: 'draft' | 'published' | 'archived'
}

export const RENEWAL_KINDS = ['insurance', 'contract', 'warranty', 'subscription', 'licence', 'other'] as const
export type RenewalKind = (typeof RENEWAL_KINDS)[number]

export const RENEWAL_KIND_LABELS: Record<RenewalKind, string> = {
  insurance: 'Insurance',
  contract: 'Contract',
  warranty: 'Warranty',
  subscription: 'Subscription',
  licence: 'Licence',
  other: 'Other',
}

/** Mirrors public.renewals — Migration 030. */
export interface Renewal {
  id: string
  user_id: string
  name: string
  kind: RenewalKind
  provider: string | null
  amount: number | null
  frequency: 'monthly' | 'annual' | 'once-off'
  renews_on: string
  expense_id: string | null
  reminder_days: number
  notes: string | null
  ended_at: string | null
  created_at: string
  updated_at: string
}

/** Monthly spend in a category from the person's active expenses. */
export function categoryMonthly(expenses: Expense[], category: string): number {
  return expenses.filter((e) => !e.deleted_at && e.category === category).reduce((s, e) => s + monthlyEquivalent(e), 0)
}

/**
 * Per-person impact of a price event, a month:
 * - % change: their monthly amount in the category × %.
 * - c/l (fuel): litres a month estimated from their transport spend ÷ the fuel price, × the change in rand.
 * - R: a flat rand change.
 * Null when it affects nothing they track (the event is then hidden for them).
 */
export function eventImpact(event: PriceEvent, expenses: Expense[], fuelPrice: number): number | null {
  const monthly = categoryMonthly(expenses, event.category)
  if (monthly <= 0) return null
  if (event.change_unit === 'c/l' && event.change_amount != null) {
    if (!(fuelPrice > 0)) return null
    const litres = monthly / fuelPrice
    return Math.round(litres * (event.change_amount / 100) * 100) / 100
  }
  if (event.change_pct != null) return Math.round(monthly * (event.change_pct / 100) * 100) / 100
  if (event.change_unit === 'R' && event.change_amount != null) return event.change_amount
  return null
}

/** The event most likely to match an expense, to prefill "Goes up every … by …%". */
export function matchingEvent(expense: Pick<Expense, 'category'>, events: PriceEvent[]): PriceEvent | null {
  return events.find((e) => e.category === expense.category && e.change_pct != null) ?? null
}

/** "↑ Jan ~9%" for an expense with its own expected increase. */
export function increaseChip(e: Pick<Expense, 'increase_month' | 'increase_pct'>): string | null {
  if (!e.increase_month || e.increase_pct == null) return null
  const month = new Date(2026, e.increase_month - 1, 1).toLocaleDateString('en-ZA', { month: 'short' })
  return `↑ ${month} ~${Math.round(e.increase_pct)}%`
}

/** The next date (1st of the month) an expense's own increase lands, on or after `today`. */
export function nextIncreaseDate(month: number, today = new Date()): Date {
  const thisYear = new Date(today.getFullYear(), month - 1, 1)
  const t = new Date(today.getFullYear(), today.getMonth(), today.getDate())
  return thisYear.getTime() >= t.getTime() ? thisYear : new Date(today.getFullYear() + 1, month - 1, 1)
}

export interface TimelineItem {
  key: string
  date: Date
  type: 'renewal' | 'price' | 'increase'
  title: string
  detail: string
  /** Extra a month (price changes, own increases) or the renewal amount. */
  amount: number | null
  link: string
}

const DAY = 86_400_000

function parseDay(d: string): Date {
  const [y, m, day] = d.split('-').map(Number)
  return new Date(y, m - 1, day)
}

/** Merged "Coming up" for the next `days` days: renewals, published price changes that affect you, your own increases. */
export function comingUp(params: {
  renewals: Renewal[]
  events: PriceEvent[]
  expenses: Expense[]
  fuelPrice: number
  today?: Date
  days?: number
}): TimelineItem[] {
  const { renewals, events, expenses, fuelPrice, today = new Date(), days = 90 } = params
  const start = new Date(today.getFullYear(), today.getMonth(), today.getDate()).getTime()
  const end = start + days * DAY
  const within = (d: Date) => d.getTime() >= start && d.getTime() <= end
  const out: TimelineItem[] = []
  for (const r of renewals) {
    if (r.ended_at) continue
    const d = parseDay(r.renews_on)
    if (!within(d)) continue
    out.push({
      key: `r:${r.id}`,
      date: d,
      type: 'renewal',
      title: `${r.name} renews`,
      detail: [RENEWAL_KIND_LABELS[r.kind], r.provider].filter(Boolean).join(' · '),
      amount: r.amount,
      link: '/renewals',
    })
  }
  for (const e of events) {
    if (e.status !== 'published') continue
    const d = parseDay(e.effective_on)
    if (!within(d)) continue
    const impact = eventImpact(e, expenses, fuelPrice)
    if (impact === null) continue
    out.push({ key: `p:${e.id}`, date: d, type: 'price', title: e.title, detail: categoryLabel(e.category), amount: impact, link: '/renewals' })
  }
  for (const x of expenses) {
    if (x.deleted_at || !x.increase_month || x.increase_pct == null) continue
    const d = nextIncreaseDate(x.increase_month, today)
    if (!within(d)) continue
    out.push({
      key: `i:${x.id}`,
      date: d,
      type: 'increase',
      title: `${x.name} goes up`,
      detail: `~${Math.round(x.increase_pct)}% (your estimate)`,
      amount: Math.round(monthlyEquivalent(x) * (x.increase_pct / 100) * 100) / 100,
      link: '/expenses',
    })
  }
  return out.sort((a, b) => a.date.getTime() - b.date.getTime())
}

/** Contract ending soon → "you could move to a SIM-only deal" style nudge. */
export function contractNudge(r: Renewal, today = new Date()): string | null {
  if (r.kind !== 'contract' || r.ended_at) return null
  const d = parseDay(r.renews_on)
  const days = Math.round((d.getTime() - new Date(today.getFullYear(), today.getMonth(), today.getDate()).getTime()) / DAY)
  if (days < 0 || days > 90) return null
  const when = d.toLocaleDateString('en-ZA', { day: 'numeric', month: 'short' })
  const cell = /phone|cell|vodacom|mtn|telkom|cell c|sim/i.test(`${r.name} ${r.provider ?? ''}`)
  return cell
    ? `Out of contract on ${when} — you could move to a SIM-only deal and keep your phone.`
    : `Out of contract on ${when} — a good time to compare quotes before it rolls over.`
}

export interface StayAheadNotice {
  kind: 'renewal' | 'price_change'
  title: string
  body: string
  link: string
  dedupe_key: string
}

/** Renewal reminders: at reminder_days (default 30) and at 7 days before. */
export function renewalNotices(r: Renewal, today: Date): StayAheadNotice[] {
  if (r.ended_at) return []
  const days = Math.round((parseDay(r.renews_on).getTime() - new Date(today.getFullYear(), today.getMonth(), today.getDate()).getTime()) / DAY)
  const marks = [...new Set([r.reminder_days, 7])].filter((m) => m > 0)
  if (!marks.includes(days)) return []
  const when = parseDay(r.renews_on).toLocaleDateString('en-ZA', { day: 'numeric', month: 'short' })
  return [
    {
      kind: 'renewal',
      title: `${r.name} renews ${when}`,
      body: r.kind === 'insurance' ? `${r.name} renews ${when}. Worth a quote?` : `${r.name} renews ${when}.`,
      link: '/renewals',
      dedupe_key: `renewal:${r.id}:${r.renews_on}:${days}`,
    },
  ]
}

/** Price change 7 days before it lands, only if it affects the person. `fmt` formats money. */
export function priceNotices(event: PriceEvent, expenses: Expense[], fuelPrice: number, today: Date, fmt: (n: number) => string): StayAheadNotice[] {
  if (event.status !== 'published') return []
  const days = Math.round((parseDay(event.effective_on).getTime() - new Date(today.getFullYear(), today.getMonth(), today.getDate()).getTime()) / DAY)
  if (days !== 7) return []
  const impact = eventImpact(event, expenses, fuelPrice)
  if (impact === null || Math.abs(impact) < 1) return []
  const when = parseDay(event.effective_on).toLocaleDateString('en-ZA', { weekday: 'short', day: 'numeric', month: 'short' })
  return [
    {
      kind: 'price_change',
      title: event.title,
      body: `${event.title} on ${when} — about ${fmt(Math.abs(impact))} ${impact >= 0 ? 'more' : 'less'} a month for you.`,
      link: '/renewals',
      dedupe_key: `price_change:${event.id}`,
    },
  ]
}
